import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input including undeclared extra properties through unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', extra: 42});

    expect({response, receivedInputs}).toEqual({
      response: {result: 'ok'},
      receivedInputs: [{location: 'Berlin', extra: 42}],
    });
  });

  it('throws Unknown tool for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool schema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition: ToolDefinition = {
      name: 'static_weather',
      description: 'Static schema read check',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };
    registry.register(definition, async () => 'ok');

    const results: string[] = [];
    for (let index = 0; index < 10; index++) {
      const response = await registry.execute('static_weather', {location: 'Oslo'});
      results.push(response.result);
    }

    expect({schemaReads, callCount: results.length}).toEqual({schemaReads: 1, callCount: 10});
  });

  it('validates function-valued definitions against the current schema and caches by reference', async () => {
    const registry = new ToolRegistry();
    const citySchema: Record<string, unknown> = {
      type: 'object',
      properties: {
        city: {type: 'string', minLength: 2},
        units: {type: 'string', enum: ['celsius', 'fahrenheit']},
        address: {
          type: 'object',
          properties: {postal: {type: 'string'}},
          required: ['postal'],
        },
      },
      required: ['city'],
    };
    const zipSchema: Record<string, unknown> = {
      type: 'object',
      properties: {zip: {type: 'string'}},
      required: ['zip'],
    };
    let activeSchema = citySchema;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Dynamic schema tool',
        inputSchema: activeSchema,
      }),
      async () => 'ok'
    );

    const firstValid = await registry.execute('dynamic_weather', {city: 'Paris'});
    const enumRejected = await registry.execute('dynamic_weather', {city: 'Paris', units: 'kelvin'});
    const nestedRejected = await registry.execute('dynamic_weather', {city: 'Paris', address: {}});
    const lengthRejected = await registry.execute('dynamic_weather', {city: 'P'});
    activeSchema = zipSchema;
    const switchedRejected = await registry.execute('dynamic_weather', {city: 'Paris'});
    const switchedValid = await registry.execute('dynamic_weather', {zip: '75001'});

    expect({
      firstValid: firstValid.result,
      enumRejected: enumRejected.result.includes('units') && enumRejected.result.includes('celsius'),
      nestedRejected: nestedRejected.result.includes('address.postal') && /required/i.test(nestedRejected.result),
      lengthRejected: lengthRejected.result.includes('city'),
      switchedRejected: switchedRejected.result.includes('zip') && /required/i.test(switchedRejected.result),
      switchedValid: switchedValid.result,
    }).toEqual({
      firstValid: 'ok',
      enumRejected: true,
      nestedRejected: true,
      lengthRejected: true,
      switchedRejected: true,
      switchedValid: 'ok',
    });
  });
});

